SOCIAL_ORDER = ['Firm_Donation', 'Language_Course', 'Rec_Letter', 'Whistleblowing',
               'Organizational_Citizenship', 'Lottery_Choice', 'Common_Goods',
               'Drought', 'Note_Taking']
MORAL_ORDER = ['Ladder', 'Tyran', 'Lifeboat', 'Suicide', 'Medicine', 'RAF', 'Rwanda',
              'Ransom', 'Tax', 'Operations', 'Vet', 'Endow', 'RobinHood']



class Study1Survey:
    """Study 1 of Cheung, Maier & Lieder (2024), "Large Language Models Amplify
    Human Biases in Moral Decision-Making" (PsyArXiv).

    Design (Materials and Methods, Study 1, p. 19-20): each participant reads
    the collective-action instruction and the moral-dilemma instruction, then
    answers 9 collective-action problems (continuous slider) followed by 13
    sacrificial moral dilemmas (Y/N), all within-subjects.

    ASSUMPTION: the paper says vignettes were presented in randomized order,
    but the shipped exp0.csv stores one fixed order for every participant
    (SOCIAL_ORDER then MORAL_ORDER); the transcript generator follows the CSV
    and so does this simulator.

    ASSUMPTION: a collective-action response token is an integer drawn
    uniformly in the vignette's stated slider range [lo, hi]; the token is the
    number itself, so the token-to-value mapping is fixed.

    ASSUMPTION: the moral-dilemma token is fixed Y/N; response 1 -> Y,
    response 0 -> N.

    The DataFrame matches exp0.csv minus the Qualtrics/demographic columns.
    """

    def __init__(self):
        self.name = "cheung_2024_large_exp0"
        self.social_order = list(SOCIAL_ORDER)
        self.moral_order = list(MORAL_ORDER)

    def simulate(self, agent, num_simulations, max_chars=None):
        rows, prompts = [], []
        plan = [(d, "collective_action") for d in self.social_order] + \
               [(d, "moral_dilemma") for d in self.moral_order]
        for sim in tqdm(range(num_simulations)):
            prompt = INSTR_SOCIAL + "\n\n" + INSTR_MORAL + "\n"
            for trial, (dit, dtype) in enumerate(plan):
                if max_chars is not None and len(prompt) >= max_chars:
                    break
                if dtype == "collective_action":
                    item = SOCIAL[dit]
                    prompt += f"\nScenario ({dit}): {item['desc']}\n"
                    prompt += "You set the slider to [HUMAN_RESPONSE]"
                    lo, hi = item["lo"], item["hi"]
                    opts = [str(x) for x in range(min(lo, hi), max(lo, hi) + 1)]
                    token = str(agent(prompt, choice_options=opts))
                    response = float(token) if token.lstrip("-").isdigit() else float("nan")
                    prompt += token + "[/HUMAN_RESPONSE].\n"
                    dtype_out = "collective_action"
                else:
                    prompt += f"\nDilemma ({dit}): {MORAL[dit]}\n"
                    prompt += "You press [HUMAN_RESPONSE]"
                    token = str(agent(prompt, choice_options=["Y", "N"]))
                    response = 1.0 if token == "Y" else 0.0
                    prompt += token + "[/HUMAN_RESPONSE].\n"
                    dtype_out = "moral_dilemma"
                rows.append(
                    {"participant_id": f"P{sim:03d}",
                     "trial": trial, "response": response,
                     "dilemma": dit, "dilemma_type": dtype_out,
                     "phase": "test", "valid": 1})
            prompts.append(prompt.strip())
        df = pd.DataFrame(rows, columns=[
            "participant_id", "trial", "response", "dilemma", "dilemma_type",
            "phase", "valid",
        ])
        df["response"] = df["response"].astype("float64")
        return df, prompts



def _random_agent(prompt, choice_options):
    return str(np.random.choice(choice_options))


def main():
    parser = argparse.ArgumentParser(
        description="Smoke-test this simulator with a uniform-random agent.")
    parser.add_argument("-n", "--num-simulations", type=int, default=3,
                        help="number of simulated participants (default: 3)")
    parser.add_argument("--max-chars", type=int, default=None,
                        help="stop each participant at the block boundary at/past this many chars")
    parser.add_argument("--seed", type=int, default=None,
                        help="numpy random seed, for reproducible runs")
    args = parser.parse_args()

    if args.seed is not None:
        np.random.seed(args.seed)

    task = Study1Survey()
    df, prompts = task.simulate(_random_agent, args.num_simulations,
                                max_chars=args.max_chars)

    print(f"name: {task.name}")
    print(f"df shape: {df.shape}")
    print("dtypes:")
    print(df.dtypes.to_string())
    print("head:")
    print(df.head(8).to_string())
    print(f"prompt lengths: {[len(p) for p in prompts]}")
    for i, p in enumerate(prompts):
        first = p.splitlines()[0]
        if len(first) > 180:
            first = first[:90] + " … " + first[-90:]
        print(f"participant {i} first line: {first}")
    print("=" * 78)
    print("first prompt, head:")
    print(prompts[0][:600])
    print("...")
    print("first prompt, tail:")
    print(prompts[0][-300:])


if __name__ == "__main__":
    main()
